def move(mv):
	err = 'Error'
	no = 'No'
	yes = 'Yes'
	if len(mv) != 5:
		return err
	elif (mv[0] < 'a' or mv[0] > 'h') or (mv[1] < '1' or mv[1] > '8') or mv[2] != '-' or (mv[3] < 'a' or mv[3] > 'h') or (mv[4] < '1' or mv[4] > '8'):
		return err
	else:
		c1 = ord(mv[0])
		c2 = ord(mv[3])
		d1 = int(mv[1])
		d2 = int(mv[4])
		if abs((c1 - c2) * (d1 - d2)) == 2:
			return yes
		else:
			return no
tc = int(input())
for _ in range(tc):
	s = input()
	print(move(s))
